// ---------------------------------------------------------------------------

function topologicalSortTasks(tasks) {
    var byKey = {};
    tasks.forEach(function(t) { byKey[t.key] = t; });

    var sorted = [];
    var visited = {};

    function visit(key) {
        if (visited[key]) return;
        visited[key] = true;
        var t = byKey[key];
        if (t) {
            t.depends_on.forEach(function(dep) { if (byKey[dep]) visit(dep); });
            sorted.push(t);
        }
    }

    tasks.forEach(function(t) { visit(t.key); });
    return sorted;
