                var key = repoName + ':' + id;
                repoTaskKeys[repoName].push(key);
                flat.push({
                    key: key,
                    repo: repoName,
                    title: t.title || id,
                    reason: t.reason || '',
                    rawDependsOn: Array.isArray(t.depends_on) ? t.depends_on : [],
                    repoLevelDependsOn: Array.isArray(repo.depends_on) ? repo.depends_on : []
