            var implicitKey = repoName + ':' + repoName;
            repoTaskKeys[repoName] = [implicitKey];
            flat.push({
                key: implicitKey,
                repo: repoName,
                title: repo.reason || repoName,
                reason: repo.reason || '',
                rawDependsOn: [],
                repoLevelDependsOn: Array.isArray(repo.depends_on) ? repo.depends_on : []
            });
